const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon(
    [[[-70.0, -8.0],
      [-70.0, -18.0],
      [-55.0, -18.0],
      [-55.0, -8.0],
      [-70.0, -8.0]]]); // A representative polygon in Western Brazil

  const start_2002 = '2002-08-01';
  const end_2002 = '2002-08-31';
  const start_2018 = '2018-08-01';
  const end_2018 = '2018-08-31';

  const COLLECTION_ID = 'MODIS/006/MCD19A2_GRANULES';
  const AOD_BAND = 'Optical_Depth_055';
  const SCALE_FACTOR = 0.001; // MODIS AOD scale factor

  // Function to mask clouds and extract AOD
  function maskAndScaleAOD(image) {
    const qa = image.select('AOD_QA');
    // Bits 0-1: Cloud Mask (00 = Clear, 01 = Cloudy, 10 = Mixed, 11 = Unused)
    // Bits 2-3: AOD_QA (00 = Good, 01 = Marginal, 10 = Poor, 11 = Unused)
    const cloudMask = qa.rightShift(0).bitwiseAnd(3); // Extract bits 0-1
    const aodQa = qa.rightShift(2).bitwiseAnd(3);     // Extract bits 2-3

    // Keep clear sky and good/marginal AOD retrievals
    const mask = cloudMask.eq(0).and(aodQa.lte(1)); // cloudMask == 'Clear' AND aodQa <= 'Marginal'

    let aod = image.select(AOD_BAND).multiply(SCALE_FACTOR);
    // Mask out values outside physically reasonable range (0 to 5 for AOD)
    aod = aod.updateMask(mask).updateMask(aod.gte(0)).updateMask(aod.lte(5));
    return aod.copyProperties(image, ['system:time_start']);
  }

  // 2. Data Acquisition & Check
  let col_2002 = ee.ImageCollection(COLLECTION_ID)
    .filterDate(start_2002, end_2002)
    .filterBounds(geometry)
    .map(maskAndScaleAOD);

  let col_2018 = ee.ImageCollection(COLLECTION_ID)
    .filterDate(start_2018, end_2018)
    .filterBounds(geometry)
    .map(maskAndScaleAOD);

  const size_2002 = await col_2002.size().getInfo();
  const size_2018 = await col_2018.size().getInfo();

  if (size_2002 === 0 || size_2018 === 0) {
    console.log(`2002 Images: ${size_2002}, 2018 Images: ${size_2018}`);
    console.log("C1: Empty Collection (No images found for one or both periods).");
    return;
  }

  // Reduce collections to a single image (mean composite)
  const img_2002 = col_2002.mean();
  const img_2018 = col_2018.mean();

  // 3. Processing (Calculate pixel count to detect C2)
  const count_2002_dict = await img_2002.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 3000, // Use a larger scale for efficiency
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const count_2018_dict = await img_2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const valid_pixels_2002 = count_2002_dict ? count_2002_dict[AOD_BAND] || 0 : 0;
  const valid_pixels_2018 = count_2018_dict ? count_2018_dict[AOD_BAND] || 0 : 0;

  if (valid_pixels_2002 === 0 || valid_pixels_2018 === 0) {
    console.log(`2002 Images: ${size_2002} (Valid Pixels: ${valid_pixels_2002})`);
    console.log(`2018 Images: ${size_2018} (Valid Pixels: ${valid_pixels_2018})`);
    console.log("C2: No Valid Pixels (after cloud masking/processing, 0 pixels remain).");
    return;
  }

  // 4. Calculation
  const mean_aod_2002_dict = await img_2002.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const mean_aod_2018_dict = await img_2018.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 3000,
    maxPixels: 1e9,
    tileScale: 16
  }).getInfo();

  const mean_aod_2002 = mean_aod_2002_dict ? mean_aod_2002_dict[AOD_BAND] : null;
  const mean_aod_2018 = mean_aod_2018_dict ? mean_aod_2018_dict[AOD_BAND] : null;

  // 5. Validation & Final Answer
  if (mean_aod_2002 === null || mean_aod_2018 === null ||
      isNaN(mean_aod_2002) || isNaN(mean_aod_2018)) {
    console.log(`2002 AOD: ${mean_aod_2002}, 2018 AOD: ${mean_aod_2018}`);
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
    return;
  }

  console.log(`2002 Images: ${size_2002} (Valid Pixels: ${valid_pixels_2002}, AOD: ${mean_aod_2002.toFixed(3)})`);
  console.log(`2018 Images: ${size_2018} (Valid Pixels: ${valid_pixels_2018}, AOD: ${mean_aod_2018.toFixed(3)})`);

  if (mean_aod_2018 < mean_aod_2002) {
    console.log("A"); // AOD decreased
  } else {
    console.log("B"); // AOD did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
